MALLS.forEach(m=>{m.name=FLOORPLANS[m.id].name;});
export const mallById=id=>MALLS.find(m=>m.id===id);
export const storeUnlock=id=>MALLS.findIndex(m=>m.sections.some(s=>s.stores.includes(id)));
export const SLOT_NAMES={top:'Top',bottom:'Bottom',shoes:'Shoes',bag:'Bag',hat:'Hat',belt:'Belt',scarf:'Scarf',watch:'Watch',jewelry:'Jewelry'};
export function slotForProduct(p){return !p?null:['shirt','hoodie','cardigan','jacket'].includes(p.type)?'top':['pants','shorts'].includes(p.type)?'bottom':['shoes','sandals'].includes(p.type)?'shoes':['bag','backpack','crossbody','duffel'].includes(p.type)?'bag':p.type==='hat'?'hat':p.type==='belt'?'belt':p.type==='scarf'?'scarf':['watch','digitalwatch'].includes(p.type)?'watch':['necklace','earrings','bracelet','ring','sunglasses'].includes(p.type)?'jewelry':null;}
